changeSet.sql:
CREATE TABLE app_user ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, deleted BOOLEAN NOT NULL DEFAULT FALSE, insert_by VARCHAR(255), insert_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, edit_by VARCHAR(255), edit_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, entity_version BIGINT NOT NULL DEFAULT 0, user_identity_id BIGINT NOT NULL UNIQUE REFERENCES public.user_identity(id) ON DELETE RESTRICT, keycloak_id VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, last_name VARCHAR(255), birth_date DATE, email VARCHAR(255), description VARCHAR(4000), active BOOLEAN NOT NULL DEFAULT TRUE ); CREATE INDEX idx_app_user_active_name ON app_user(active, deleted, name, last_name);
CREATE TABLE app_user_role ( user_id BIGINT NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, role VARCHAR(64) NOT NULL, PRIMARY KEY (user_id, role) );
CREATE TABLE instrument ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, deleted BOOLEAN NOT NULL DEFAULT FALSE, insert_by VARCHAR(255), insert_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, edit_by VARCHAR(255), edit_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, entity_version BIGINT NOT NULL DEFAULT 0, name VARCHAR(255) NOT NULL, description VARCHAR(4000) ); CREATE INDEX idx_instrument_name ON instrument(deleted, name);
CREATE TABLE user_instrument ( user_id BIGINT NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, instrument_id BIGINT NOT NULL REFERENCES instrument(id) ON DELETE RESTRICT, display_order INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (user_id, instrument_id), UNIQUE (user_id, display_order) );
CREATE TABLE album ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, deleted BOOLEAN NOT NULL DEFAULT FALSE, insert_by VARCHAR(255), insert_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, edit_by VARCHAR(255), edit_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, entity_version BIGINT NOT NULL DEFAULT 0, name VARCHAR(255) NOT NULL, description VARCHAR(4000), album_date DATE, state VARCHAR(32) );
CREATE TABLE track ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, deleted BOOLEAN NOT NULL DEFAULT FALSE, insert_by VARCHAR(255), insert_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, edit_by VARCHAR(255), edit_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, entity_version BIGINT NOT NULL DEFAULT 0, name VARCHAR(255) NOT NULL, sub_name VARCHAR(255), description VARCHAR(4000), composer VARCHAR(255), arranger VARCHAR(255), tempo VARCHAR(255), tone VARCHAR(255), state VARCHAR(32) ); CREATE INDEX idx_track_search ON track(deleted, state, name);
CREATE TABLE track_type ( track_id BIGINT NOT NULL REFERENCES track(id) ON DELETE CASCADE, type VARCHAR(255) NOT NULL, PRIMARY KEY (track_id, type) );
CREATE TABLE album_track ( album_id BIGINT NOT NULL REFERENCES album(id) ON DELETE CASCADE, track_id BIGINT NOT NULL REFERENCES track(id) ON DELETE RESTRICT, display_order INTEGER NOT NULL, PRIMARY KEY (album_id, track_id), UNIQUE (album_id, display_order) );
CREATE TABLE sheet_music ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, track_id BIGINT NOT NULL REFERENCES track(id) ON DELETE CASCADE, description VARCHAR(4000), display_order INTEGER NOT NULL, needs_review BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE (track_id, display_order) );
CREATE TABLE media ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, deleted BOOLEAN NOT NULL DEFAULT FALSE, insert_by VARCHAR(255), insert_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, edit_by VARCHAR(255), edit_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, entity_version BIGINT NOT NULL DEFAULT 0, name VARCHAR(255) NOT NULL, description VARCHAR(4000), path VARCHAR(2048) NOT NULL, content_type VARCHAR(255) );
CREATE TABLE sheet_music_media ( sheet_music_id BIGINT NOT NULL REFERENCES sheet_music(id) ON DELETE CASCADE, media_id BIGINT NOT NULL REFERENCES media(id) ON DELETE RESTRICT, display_order INTEGER NOT NULL, PRIMARY KEY (sheet_music_id, media_id), UNIQUE (sheet_music_id, display_order) );
CREATE TABLE sheet_music_instrument ( sheet_music_id BIGINT NOT NULL REFERENCES sheet_music(id) ON DELETE CASCADE, instrument_id BIGINT NOT NULL REFERENCES instrument(id) ON DELETE RESTRICT, display_order INTEGER NOT NULL, PRIMARY KEY (sheet_music_id, instrument_id), UNIQUE (sheet_music_id, display_order) );
CREATE TABLE calendar_event ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, deleted BOOLEAN NOT NULL DEFAULT FALSE, insert_by VARCHAR(255), insert_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, edit_by VARCHAR(255), edit_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, entity_version BIGINT NOT NULL DEFAULT 0, name VARCHAR(255) NOT NULL, description VARCHAR(4000), state VARCHAR(32), start_date TIMESTAMPTZ NOT NULL, end_date TIMESTAMPTZ NOT NULL, location VARCHAR(1000), fee NUMERIC(19,4), reminder_minutes INTEGER ); CREATE INDEX idx_calendar_event_range ON calendar_event(deleted, state, start_date, end_date);
CREATE TABLE calendar_event_cost ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id BIGINT NOT NULL REFERENCES calendar_event(id) ON DELETE CASCADE, description VARCHAR(1000) NOT NULL, amount NUMERIC(19,4), display_order INTEGER NOT NULL );
CREATE TABLE calendar_event_availability ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id BIGINT NOT NULL REFERENCES calendar_event(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, availability VARCHAR(16) NOT NULL CHECK (availability IN ('AVAILABLE', 'UNAVAILABLE')), response_date TIMESTAMPTZ NOT NULL, UNIQUE (event_id, user_id) );
CREATE TABLE calendar_event_presence ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id BIGINT NOT NULL REFERENCES calendar_event(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, arrival_time TIMESTAMPTZ, note VARCHAR(2000), display_order INTEGER NOT NULL, UNIQUE (event_id, user_id), UNIQUE (event_id, display_order) );
CREATE TABLE upload_job ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, deleted BOOLEAN NOT NULL DEFAULT FALSE, insert_by VARCHAR(255), insert_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, edit_by VARCHAR(255), edit_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, entity_version BIGINT NOT NULL DEFAULT 0, user_id BIGINT NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, track_id BIGINT REFERENCES track(id) ON DELETE SET NULL, name VARCHAR(255), description VARCHAR(4000), path VARCHAR(2048) NOT NULL, status VARCHAR(32) NOT NULL, type VARCHAR(255) );
